import{_ as a,o as t,c as i,a0 as o}from"./chunks/framework.BLL-IG04.js";const m=JSON.parse('{"title":"How-to: audit the memory layer","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/kuda-audit.md","filePath":"how-to/kuda-audit.md"}'),r={name:"how-to/kuda-audit.md"};function d(s,e,n,h,c,l){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="how-to-audit-the-memory-layer" tabindex="-1">How-to: audit the memory layer <a class="header-anchor" href="#how-to-audit-the-memory-layer" aria-label="Permalink to &quot;How-to: audit the memory layer&quot;">​</a></h1><p><code>mimus audit</code> applies the same claim machinery to <code>.kuda/</code> cards — agent memory gets a trust score, not a free pass.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span></span></code></pre></div><p>Per card it verifies:</p><ul><li>every <code>verify:</code> file still exists</li><li>card <code>provenance.files</code> hashes match current content</li><li>symbols claimed in <code>api:</code> resolve in the index</li><li><code>deps:</code> edges match the real dep graph</li></ul><h2 id="reading-the-score" tabindex="-1">Reading the score <a class="header-anchor" href="#reading-the-score" aria-label="Permalink to &quot;Reading the score&quot;">​</a></h2><p>Each card reports <code>trust</code>: fresh | drifted | contradicted. Drifted cards should be regenerated (<code>kuda sync</code>); contradicted cards need attention — either the code moved without a sync, or the summarizer invented something (a bug worth reporting).</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>Memory without falsification decays into confident confabulation. The audit is what makes a kuda index <em>trustworthy</em> rather than merely <em>present</em>.</p>',10)])])}const p=a(r,[["render",d]]);export{m as __pageData,p as default};
